const kHTTPResponse: unique symbol = /* @__PURE__ */ Symbol.for("h3.HTTPResponse");

export class HTTPResponse {
  #headers?: Headers;
  #init?: Pick<ResponseInit, "status" | "statusText" | "headers"> | undefined;
  body?: BodyInit | null;
