389	      // With no `onError` configured, `errorResponse()`'s `JSON.stringify` runs
390	      // synchronously in the same pass as the throw (the async/onError branch is not
391	      // taken), so this exercises the raw synchronous-escape path directly.
392	      t.app.config.onError = undefined;
393	      t.app.use(() => {
