404	  // Regression for #1503 (CodeRabbit): a synchronously-throwing `onError` hook must not
405	  // recurse infinitely. `Promise.resolve(onError(error, event))` evaluates the call before
406	  // wrapping it in a promise, so a sync throw there escaped `prepareResponse()` synchronously.
407	  // That was caught by `toResponse()`'s try/catch (added for #1477) and re-entered
408	  // `toResponse` with `nested` reset to `false` — calling the same throwing `onError` again,
409	  // forever (stack overflow instead of a normalized 500).
410	  it("a synchronously-throwing onError does not recurse infinitely", async () => {
411	    t.app.config.onError = () => {
412	      throw new Error("onError boom");
413	    };
414	    t.app.use(() => {
415	      throw new Error("handler boom");
416	    });
417	
418	    const res = await t.fetch("/");
