422	
423	  // A value returned from `onError` replaces the response, so a value *thrown* by the hook must be
424	  // normalized through `toError()` first. Otherwise the two are indistinguishable and a non-Error
425	  // throw is rendered as a successful body: the hook's internals leak to the client and the failed
426	  // request reports 200.
427	  for (const [label, thrown] of [
428	    ["an object", { secret: "s3cr3t" }],
429	    ["a string", "leaked internal string"],
430	  ] as const) {
431	    it(`an onError throwing ${label} renders an unhandled 500, not a 200 body`, async () => {
432	      t.app.config.onError = () => {
433	        throw thrown;
434	      };
435	      t.app.use(() => {
436	        throw new Error("handler boom");
437	      });
438	
439	      const res = await t.fetch("/");
440	      expect(res.status).toBe(500);
441	      const body = await res.json();
442	      expect(body).toMatchObject({ status: 500, unhandled: true });
443	      expect(JSON.stringify(body)).not.toContain("s3cr3t");
444	      expect(JSON.stringify(body)).not.toContain("leaked internal string");
445	    });
446	  }
447	
448	  it("an onError throwing a number renders that status", async () => {
449	    t.app.config.onError = () => {
450	      throw 418;
451	    };
452	    t.app.use(() => {
453	      throw new Error("handler boom");
454	    });
455	
456	    const res = await t.fetch("/");
457	    expect(res.status).toBe(418);
458	  });
459	});
